    margin-top:1mm;
    font-size:3.3mm;
    color:#0d1b4c;
    font-weight:700;
    line-height:1.15;
  }

  /* ---------- PRINT ---------- */
  /* Positioned off-screen (not display:none) so its layout is measurable —
     fitNameToWidth() needs real clientWidth/scrollWidth before print kicks in. */
  #printArea{
    position:absolute;
    top:0;
    left:-9999px;
  }

  /* ---------- SAVE AS PDF (rendered off-screen at true mm size, no scale transform) ---------- */
  #pdfArea{
    position:absolute;
    top:0;
    left:-9999px;
  }
  .pdf-card{
    width:53.98mm;
    height:85.6mm;
    position:relative;
    overflow:hidden;
    background:#fff;
  }
  @media print{
    @page{ size:53.98mm 85.6mm; margin:0; }
    .topbar{display:none;}
    .app{display:none;}
    #printArea{
      position:absolute;
      top:0; left:0;
    }
    #printArea .card{
      position:relative;
      top:auto; left:auto;
      transform:none;
      margin:0;
      box-shadow:none;
      border-radius:0;
      page-break-after:always;
      width:53.98mm;
      height:85.6mm;
    }
    #printArea .card:last-child{page-break-after:auto;}
  }
</style>
</head>
<body>
