    <div class="field">
      <label>Full Name</label>
      <input type="text" id="fullName" placeholder="e.g. Ahmed Shazeen" value="">
    </div>

    <div class="row2">
      <div class="field">
        <label>RC number</label>
        <input type="text" id="rcNumber" placeholder="e.g. 48440" value="">
      </div>
      <div class="field">
        <label>Designation</label>
        <input type="text" id="designation" placeholder="e.g. Immigration Officer" value="">
      </div>
    </div>

    <hr class="sep">

    <div class="opts">
      <label><input type="checkbox" id="printBack" checked> Include back side when printing</label>
    </div>

    <div class="btnbar">
      <button class="btn-primary" onclick="printCard()">Print card</button>
      <button class="btn-secondary" id="savePdfBtn" onclick="savePDF()">Save as PDF</button>
    </div>
    <div class="btnbar">
      <button class="btn-secondary" id="saveRecordBtn" onclick="saveRecord()">Save to records</button>
      <button class="btn-secondary" onclick="resetForm()">Reset</button>
    </div>

    <p class="note">
      Printing uses a fixed CR-80 page size (53.98&nbsp;mm × 85.6&nbsp;mm). In the print dialog,
      set paper size to match your card feeder and scale to <b>100% / Actual size</b> (not "Fit to page").
      "Save as PDF" downloads the same card as a CR-80-sized PDF file instead of opening the print dialog.
      Clicking "Print card" automatically saves this card to your saved cards (with a snapshot) so you
      can reprint it later — or use "Save to records" to save it without printing yet. See
      <a href="saved-cards.php">Saved cards</a> in the top bar to browse, reload, or reprint past cards.
    </p>
  </div>

  <!-- ===================== PREVIEW PANEL ===================== -->
  <div class="preview-wrap">
    <div class="cards-row">
      <div>
        <div class="card-label">Front</div>
        <div class="card-wrap"><div class="card" id="cardFrontPreview"></div></div>
      </div>
      <div>
        <div class="card-label">Back</div>
        <div class="card-wrap"><div class="card" id="cardBackPreview"></div></div>
      </div>
    </div>
  </div>
</div>

<!-- Hidden container used only for printing (populated at print time) -->
<div id="printArea"></div>

<!-- Hidden container used only for PDF export (populated when saving) -->
<div id="pdfArea"></div>

<!-- ===================== TEMPLATES ===================== -->
<template id="tplFront">
  <img class="card-bg" src="data:image/png;base64," alt="">
  <div class="photo-box" data-slot="photo">
    <div class="ph-placeholder">Photo</div>
  </div>
  <div class="id-block">
    <div class="id-name" data-field="fullName"></div>
    <div class="id-rc" data-field="rcNumber"></div>
    <div class="id-designation" data-field="designation"></div>
  </div>
</template>

<template id="tplBack">
  <img class="card-bg" src="data:image/png;base64," alt="">
</template>

<script>
let photoDataUrl = null;

function readFile(input, cb){
  const file = input.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = e => cb(e.target.result);
  reader.readAsDataURL(file);
}

document.getElementById('photoInput').addEventListener('change', e=>{
  readFile(e.target, url=>{ photoDataUrl = url; render(); });
});

const fieldIds = ['fullName','rcNumber','designation'];
fieldIds.forEach(id=>{
  document.getElementById(id).addEventListener('input', render);
});

function getValues(){
  const v = {};
  fieldIds.forEach(id=> v[id] = document.getElementById(id).value);
  return v;
}

function fitNameToWidth(el){
  const maxSize = 3.8, minSize = 2.0, step = 0.1;
  let size = maxSize;
  el.style.fontSize = size + 'mm';
  while(el.scrollWidth > el.clientWidth + 0.5 && size > minSize){
    size -= step;
    el.style.fontSize = size + 'mm';
  }
}

function buildCard(templateId, container, values){
  container.innerHTML = '';
  const tpl = document.getElementById(templateId).content.cloneNode(true);
  container.appendChild(tpl);

  container.querySelectorAll('[data-field]').forEach(el=>{
    const key = el.getAttribute('data-field');
    el.textContent = values[key] || '';
  });

  const photoSlot = container.querySelector('[data-slot="photo"]');
  if(photoSlot){
    if(photoDataUrl){
      photoSlot.innerHTML = '<img src="'+photoDataUrl+'">';
    } else {
      photoSlot.innerHTML = '<div class="ph-placeholder">Photo</div>';
    }
  }

  const nameEl = container.querySelector('.id-name');
  if(nameEl) fitNameToWidth(nameEl);
}

function render(){
  const values = getValues();
  buildCard('tplFront', document.getElementById('cardFrontPreview'), values);
  buildCard('tplBack', document.getElementById('cardBackPreview'), values);
}

async function printCard(){
  const values = getValues();

  try{
    await persistRecord(values);
  } catch(err){
    // Don't block printing if saving the record fails — just log it.
    console.error('Could not save record before printing:', err);
  }

  const printArea = document.getElementById('printArea');
  printArea.innerHTML = '';

  const frontCard = document.createElement('div');
  frontCard.className = 'card';
  printArea.appendChild(frontCard);
  buildCard('tplFront', frontCard, values);

  if(document.getElementById('printBack').checked){
    const backCard = document.createElement('div');
    backCard.className = 'card';
    printArea.appendChild(backCard);
    buildCard('tplBack', backCard, values);
  }

  window.print();
}

async function savePDF(){
  const btn = document.getElementById('savePdfBtn');
  const originalLabel = btn.textContent;
  btn.disabled = true;
  btn.textContent = 'Generating…';

  try{
    const values = getValues();
    const pdfArea = document.getElementById('pdfArea');
    pdfArea.innerHTML = '';

    const frontDiv = document.createElement('div');
    frontDiv.className = 'pdf-card';
    pdfArea.appendChild(frontDiv);
    buildCard('tplFront', frontDiv, values);

    let backDiv = null;
    if(document.getElementById('printBack').checked){
      backDiv = document.createElement('div');
      backDiv.className = 'pdf-card';
      pdfArea.appendChild(backDiv);
      buildCard('tplBack', backDiv, values);
    }

    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit:'mm', format:[53.98,85.6] });

    const frontCanvas = await html2canvas(frontDiv, { scale:3, useCORS:true, backgroundColor:'#ffffff' });
    doc.addImage(frontCanvas.toDataURL('image/jpeg', 0.92), 'JPEG', 0, 0, 53.98, 85.6);

    if(backDiv){
      const backCanvas = await html2canvas(backDiv, { scale:3, useCORS:true, backgroundColor:'#ffffff' });
      doc.addPage([53.98,85.6]);
      doc.addImage(backCanvas.toDataURL('image/jpeg', 0.92), 'JPEG', 0, 0, 53.98, 85.6);
    }

    const slugify = s => (s || '').trim().replace(/[^a-z0-9]+/gi,'_').replace(/^_+|_+$/g,'');
    const safeName = [slugify(values.fullName), slugify(values.rcNumber)].filter(Boolean).join('_') || 'card';
    doc.save(safeName + '.pdf');

    pdfArea.innerHTML = '';
  } catch(err){
    console.error(err);
    alert('Could not generate the PDF: ' + err.message);
  } finally {
    btn.disabled = false;
    btn.textContent = originalLabel;
  }
}

function resetForm(){
  document.getElementById('fullName').value = '';
  document.getElementById('rcNumber').value = '';
  document.getElementById('designation').value = '';
  document.getElementById('photoInput').value = '';
  photoDataUrl = null;
  render();
}

/* ===================== SAVED CARDS (IndexedDB) =====================
   Stores the entered fields plus a rendered snapshot of the front card,
   so a past card can be reprinted later without re-entering anything. */
const DB_NAME = 'officeCardDB';
const DB_STORE = 'cards';

function openCardDB(){
  return new Promise((resolve,reject)=>{
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = ()=>{
      const db = req.result;
      if(!db.objectStoreNames.contains(DB_STORE)){
        const store = db.createObjectStore(DB_STORE, { keyPath:'id', autoIncrement:true });
        store.createIndex('createdAt','createdAt',{unique:false});
      }
    };
    req.onsuccess = ()=>resolve(req.result);
    req.onerror = ()=>reject(req.error);
  });
}

async function dbAdd(record){
  const db = await openCardDB();
  return new Promise((resolve,reject)=>{
    const tx = db.transaction(DB_STORE,'readwrite');
    const req = tx.objectStore(DB_STORE).add(record);
    req.onsuccess = ()=>resolve(req.result);
    req.onerror = ()=>reject(req.error);
  });
}

async function dbGet(id){
  const db = await openCardDB();
  return new Promise((resolve,reject)=>{
    const tx = db.transaction(DB_STORE,'readonly');
    const req = tx.objectStore(DB_STORE).get(id);
    req.onsuccess = ()=>resolve(req.result);
    req.onerror = ()=>reject(req.error);
  });
}

async function renderFrontSnapshot(values){
  const pdfArea = document.getElementById('pdfArea');
  pdfArea.innerHTML = '';
  const div = document.createElement('div');
  div.className = 'pdf-card';
  pdfArea.appendChild(div);
  buildCard('tplFront', div, values);
  const canvas = await html2canvas(div, { scale:3, useCORS:true, backgroundColor:'#ffffff' });
  const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
  pdfArea.innerHTML = '';
  return dataUrl;
}

/* Shared save logic used both by the explicit "Save to records" button
   and automatically whenever a card is printed. Returns false (without
   throwing) when there's nothing worth saving — an all-blank form. */
async function persistRecord(values){
  if(!values.fullName.trim() && !values.rcNumber.trim()){
    return false;
  }
  const snapshot = await renderFrontSnapshot(values);
  await dbAdd({
    fullName: values.fullName,
    rcNumber: values.rcNumber,
    designation: values.designation,
    photoDataUrl: photoDataUrl,
    frontSnapshot: snapshot,
    createdAt: Date.now()
  });
  return true;
}

async function saveRecord(){
  const values = getValues();
  if(!values.fullName.trim() && !values.rcNumber.trim()){
    alert('Enter at least a name or RC number before saving.');
    return;
  }

  const btn = document.getElementById('saveRecordBtn');
  const originalLabel = btn.textContent;
  btn.disabled = true;
  btn.textContent = 'Saving…';

  try{
    await persistRecord(values);
  } catch(err){
    console.error(err);
    alert('Could not save record: ' + err.message);
  } finally {
    btn.disabled = false;
    btn.textContent = originalLabel;
  }
}

async function loadRecord(id){
  const r = await dbGet(id);
  if(!r) return;
  document.getElementById('fullName').value = r.fullName || '';
  document.getElementById('rcNumber').value = r.rcNumber || '';
  document.getElementById('designation').value = r.designation || '';
  photoDataUrl = r.photoDataUrl || null;
  render();
  window.scrollTo({ top:0, behavior:'smooth' });
}

async function reprintRecord(id){
  const r = await dbGet(id);
  if(!r) return;

  const printArea = document.getElementById('printArea');
  printArea.innerHTML = '';

  const frontCard = document.createElement('div');
  frontCard.className = 'card';
  const img = document.createElement('img');
  img.className = 'card-bg';
  img.src = r.frontSnapshot;
  frontCard.appendChild(img);
  printArea.appendChild(frontCard);

  if(document.getElementById('printBack').checked){
    const backCard = document.createElement('div');
    backCard.className = 'card';
    printArea.appendChild(backCard);
    buildCard('tplBack', backCard, {});
  }

  window.print();
}

function applyRolePermissions(){
  if(window.APP_ROLE !== 'viewer') return;

  ['photoInput','fullName','rcNumber','designation'].forEach(id=>{
    const el = document.getElementById(id);
    if(el) el.disabled = true;
  });

  const saveBtn = document.getElementById('saveRecordBtn');
  if(saveBtn){
    saveBtn.disabled = true;
    saveBtn.title = 'View-only access — cannot save new records.';
  }
}

applyRolePermissions();
render();

(function(){
  const params = new URLSearchParams(window.location.search);
  const printId = params.get('print');
  const loadId = params.get('load');
  if(printId){
    reprintRecord(Number(printId));
  } else if(loadId){
    loadRecord(Number(loadId));
  }
  if(printId || loadId){
    history.replaceState(null, '', 'index.php');
  }
})();
</script>

</body>
</html>
